window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[281]={"id":"281","numero":281,"titre":"Pancréatite chronique","objectifs":[{"id":"281-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une pancréatite chronique","contenu":"<p>La <span class=\"kw-def\">pancréatite chronique (PC)</span> est une <span class=\"kw-def\">inflammation chronique du pancréas</span> responsable de deux conséquences successives :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Fibrose mutilante progressive</span> du <span class=\"kw-def\">parenchyme pancréatique</span></li>\n        <li>Puis <span class=\"kw-alerte\">destruction fonctionnelle ± complète</span> de la glande dans un second temps</li>\n      </ul>\n      <p><strong>Mécanisme</strong> — la PC résulte de <span class=\"kw-def\">l'inhibition ou du dépassement des mécanismes de protection contre l'auto-digestion</span> du pancréas :</p>\n      <ul>\n        <li>La répétition des pancréatites active <span class=\"kw-clinique\">les</span> mécanismes de réparation et aboutit au dépôt de <span class=\"kw-alerte\">fibrose</span>, ce qui désorganise l'architecture de la glande et nuit à son bon fonctionnement</li>\n        <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">canaux pancréatiques</span> deviennent <span class=\"kw-radio\">sténosés de façon irrégulière</span></li>\n        <li>Des <span class=\"kw-radio\">calcifications</span> se forment au sein de ces canaux</li>\n      </ul>\n      <p><strong>Tissus touchés</strong> — l'atteinte se fait en deux temps :</p>\n      <ul>\n        <li>Le <span class=\"kw-def\">tissu exocrine</span> est touché en premier (<span class=\"kw-def\">acini</span>, <span class=\"kw-def\">canaux pancréatiques</span>)</li>\n        <li>Le <span class=\"kw-def\">tissu endocrine</span> est touché ensuite (<span class=\"kw-def\">îlots de Langerhans</span>)</li>\n      </ul>","frequence":0},{"id":"281-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principaux éléments d’épidémiologie d’une pancréatite chronique","contenu":"<p>La <span class=\"kw-def\">pancréatite chronique</span> est une maladie qui évolue sur une <span class=\"kw-chiffre\">longue période, de 15 à 20 ans</span>.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Prévalence</span> (pays occidentaux)</td><td><span class=\"kw-chiffre\">25 / 100 000 habitants</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Sex-ratio</span></td><td>Prédominance masculine — <span class=\"kw-chiffre\">4 H / 1 F</span> (soit <span class=\"kw-chiffre\">80 %</span> d'hommes)</td></tr>\n          <tr><td><span class=\"kw-bio\">Âge moyen</span> au 1ᵉʳ symptôme</td><td><span class=\"kw-chiffre\">40 ans</span></td></tr>\n          <tr><td>Durée d'<span class=\"kw-clinique\">évolution</span></td><td><span class=\"kw-chiffre\">15 à 20 ans</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"281-3","rang":"A","rubrique":"Etiologies","titre":"Connaître la principale cause et facteur de risque de la pancréatite chronique","contenu":"<p>Il existe <strong>deux causes principales</strong> de <span class=\"kw-def\">pancréatite chronique</span> en Occident : la <span class=\"kw-etio\">consommation d'<span class=\"kw-etio\">alcool</span></span> (cause) et le <span class=\"kw-etio\">tabac</span> (<span class=\"kw-def\">facteur de risque</span> indépendant).</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Consommation excessive d'alcool</span></td>\n            <td>\n              <strong>1ʳᵉ cause :</strong> <span class=\"kw-chiffre\">70 à 85 %</span> des PC en Occident <br>\n              <strong>Dose :</strong> <span class=\"kw-etio\">consommation d'<span class=\"kw-etio\">alcool</span></span> pur estimée à <span class=\"kw-chiffre\">100 à 150 g/jour pendant 10 à 15 ans</span> (soit environ 10-15 verres/jour), mais <strong>il n'existe pas de réelle dose-seuil</strong> <br>\n              <strong>Susceptibilité individuelle :</strong> seuls <span class=\"kw-chiffre\">moins de 5 %</span> des consommateurs excessifs d'<span class=\"kw-etio\">alcool</span> développent une PC\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Tabac</span></td>\n            <td>\n              <strong><span class=\"kw-def\">Facteur de risque</span> indépendant</strong>, associé dans <span class=\"kw-chiffre\">plus de 80 %</span> des PC d'origine alcoolique <br>\n              <strong>Facteur péjoratif</strong> qui <span class=\"kw-alerte\">aggrave l'évolution</span> de la maladie\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 75 — Addiction <span class=\"kw-etio\">Tabac</span></em></p>","frequence":0},{"id":"281-4","rang":"B","rubrique":"Etiologies","titre":"Connaître deux causes plus rares de pancréatite chronique","contenu":"<p>Hors <span class=\"kw-etio\">alcool</span>, plusieurs causes plus rares doivent être connues — ce sont globalement <span class=\"kw-clinique\">les</span> mêmes que celles de la <span class=\"kw-etio\">pancréatite aiguë</span>. Les <strong>deux principales</strong> sont la cause <span class=\"kw-etio\">obstructive</span> et la cause <span class=\"kw-etio\">auto-immune</span>.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Obstructive</span></td>\n            <td>\n              PC par obstruction du <span class=\"kw-radio\">canal de Wirsung</span> :<br>\n              <strong>Obstacle <span class=\"kw-etio\">tumoral</span> :</strong> bénin ou malin, kystique ou solide, d'<span class=\"kw-clinique\">évolution</span> lente (TIPMP, TNE) ;<br>\n              <strong>Sténose :</strong> secondaire à un traumatisme, séquelle de <span class=\"kw-etio\">pancréatite aiguë</span> ;<br>\n              <strong>Anomalie</strong> de formation des canaux pancréatiques\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Auto-immune</span></td>\n            <td>\n              <span class=\"kw-etio\">Pancréatite lympho-plasmocytaire sclérosante</span>, de présentation parfois <span class=\"kw-alerte\">pseudo-tumorale</span> :<br>\n              <strong>Type 1 :</strong> dans le cadre de la <span class=\"kw-etio\">maladie à IgG4</span> ;<br>\n              <strong>Type 2 :</strong> parfois associée à une <span class=\"kw-etio\">MICI</span> ;<br>\n              <strong>Imagerie évocatrice :</strong> sténoses canalaires étagées <strong>sans dilatation</strong> (<span class=\"kw-def\">diagnostic différentiel</span> avec une PC classique) ;<br>\n              <strong>Particularité :</strong> <span class=\"kw-ttt\">sensible aux corticoïdes</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Métaboliques</span></td>\n            <td>\n              <strong>Hypercalcémie</strong> (<span class=\"kw-chiffre\">&gt; 3 mmol/L</span>) — l'hyperparathyroïdie représente <span class=\"kw-chiffre\">&lt; 1 %</span> des PC, mais la PC complique <span class=\"kw-chiffre\">7 %</span> des hyperparathyroïdies ;<br>\n              <strong><span class=\"kw-etio\">Hypertriglycéridémie</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Génétiques</span></td>\n            <td>\n              <strong>Hors programme</strong> — à évoquer chez le sujet jeune avec contexte familial :<br>\n              Mutation du gène du <strong>trypsinogène cationique</strong> (transmission autosomique dominante) ;<br>\n              Gènes <strong>SPINK1</strong> ou <strong>CFTR</strong> (transmission autosomique récessive)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Idiopathiques</span></td>\n            <td>Aucune cause retrouvée dans <span class=\"kw-chiffre\">10 %</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège ⚠</strong> — la <span class=\"kw-ci\">lithiase des voies biliaires</span> est responsable de <strong><span class=\"kw-etio\">pancréatite aiguë</span></strong>, et <strong>PAS</strong> de <span class=\"kw-def\">pancréatite chronique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 308 — Tumeur pancréas · 282 — <span class=\"kw-etio\">MICI</span> · 268 — Hypercalcémie</em></p>","frequence":0},{"id":"281-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de la douleur de pancréatite chronique","contenu":"<p>La <span class=\"kw-clinique\">douleur pancréatique chronique</span> est présente chez <span class=\"kw-chiffre\">80 %</span> des patients. Elle est <strong>émaillée de poussées de <span class=\"kw-etio\">pancréatite aiguë</span></strong> et se présente sous deux formes :</p>\n      <ul>\n        <li><strong>Type A :</strong> <span class=\"kw-clinique\">poussées douloureuses intermittentes</span>, séparées par des périodes de <span class=\"kw-clinique\">rémission</span></li>\n        <li><span class=\"kw-clinique\">Douleur continue</span> avec des <span class=\"kw-clinique\">accès douloureux plus vifs</span></li>\n      </ul>\n      <p><strong>Conséquence — <span class=\"kw-clinique\">amaigrissement</span> :</strong> <span class=\"kw-clinique\">les</span> patients <span class=\"kw-clinique\">restreignent leur alimentation</span> car celle-ci déclenche les douleurs, ce qui entraîne un <span class=\"kw-clinique\">amaigrissement</span>.</p>\n      <div class=\"callout callout-info\"><strong>Examen physique</strong> — il n'existe <strong>aucun signe physique spécifique</strong>. L'<span class=\"kw-clinique\">examen clinique est souvent pauvre</span> : le pancréas est un organe profond, normalement impalpable.</div>","frequence":1},{"id":"281-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques des principales complications de la pancréatite chronique","contenu":"<p>Objectif dense — <span class=\"kw-clinique\">les</span> complications de la PC sont multiples. Chaque ligne correspond à une entité à reconnaître cliniquement.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Manifestations cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Pancréatite aiguë</span></td><td>Forme fréquente de révélation de la PC — <span class=\"kw-chiffre\">40 à 50 %</span> de risque de PA dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 premières années</span> d'une PC alcoolique, puis la fréquence diminue à mesure que le parenchyme se fibrose</td></tr>\n          <tr><td>Collections liquidiennes</td><td>Compliquent <span class=\"kw-chiffre\">20 à 40 %</span> des PC — <strong>pseudo-kyste</strong> ou collection nécrotique organisée</td></tr>\n          <tr><td><span class=\"kw-clinique\">Insuffisance pancréatique exocrine</span></td><td>Survient dans <span class=\"kw-clinique\">les</span> formes très évoluées (destruction de <span class=\"kw-chiffre\">&gt; 90 %</span> du tissu exocrine), presque inéluctablement <span class=\"kw-chiffre\">après 10 ans</span> d'<span class=\"kw-clinique\">évolution</span> : <span class=\"kw-clinique\">amaigrissement</span> + <span class=\"kw-clinique\">stéatorrhée</span> ; confirmée par un dosage <span class=\"kw-bio\">d'élastase fécale</span> effondré.<br><strong>Sémiologie de la <span class=\"kw-clinique\">stéatorrhée</span></strong> ⭐ (tombée en annale) : selles <span class=\"kw-clinique\">claires, couleur mastic</span>, très <span class=\"kw-clinique\">nauséabondes</span>, <span class=\"kw-clinique\">flottantes</span> à la surface de l'eau, <span class=\"kw-clinique\">collantes</span> et tachant le papier hygiénique comme un corps gras</td></tr>\n          <tr><td><span class=\"kw-etio\">Diabète</span> secondaire</td><td>Complication majeure, tardive mais quasi-inéluctable, d'abord non insulinodépendante puis insulinodépendante ; <strong>peut être la circonstance de découverte</strong> de la PC dans <span class=\"kw-clinique\">les</span> rares formes indolores ; risque de <span class=\"kw-etio\">diabète</span> insulinodépendant <span class=\"kw-chiffre\">1/3 après 15 ans</span> d'<span class=\"kw-clinique\">évolution</span> ; <span class=\"kw-alerte\">hypoglycémies fréquentes</span> (<span class=\"kw-etio\">alcoolisme</span>, baisse de la sécrétion de <span class=\"kw-ttt\">glucagon</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Dénutrition</span></td><td>Carence en <span class=\"kw-bio\">vitamines liposolubles A, D, E, K</span>, en <span class=\"kw-bio\">vitamines B12 et B9</span>, en <span class=\"kw-bio\">oligo-éléments (calcium, zinc)</span> ; risque d'<span class=\"kw-alerte\">ostéoporose</span> par hyperparathyroïdie secondaire (malabsorption de la <span class=\"kw-bio\">vitamine D</span>)</td></tr>\n          <tr><td>Dégénérescence</td><td>La PC augmente le risque d'<span class=\"kw-alerte\">adénocarcinome pancréatique</span> ; ne justifie <strong>pas</strong> de <span class=\"kw-def\">surveillance</span> particulière car le risque reste <span class=\"kw-chiffre\">&lt; 5 %</span></td></tr>\n          <tr><td>Complications hépato-biliaires</td><td>Compression de la <strong>VBP intrapancréatique</strong> (par fibrose, inflammation ou pseudo-kyste) → <span class=\"kw-clinique\">cholestase anictérique</span>, plus rarement ictérique ; peut se compliquer d'une <strong><span class=\"kw-clinique\">angiocholite</span></strong>, voire d'une <strong><span class=\"kw-etio\">cirrhose</span> biliaire secondaire</strong></td></tr>\n          <tr><td>Compression duodénale</td><td>Par fibrose, inflammation ou pseudo-kyste → <span class=\"kw-clinique\">douleurs, vomissements, intolérance alimentaire</span></td></tr>\n          <tr><td>Épanchements des séreuses</td><td><span class=\"kw-clinique\">Ascite</span> (voire pleurésie, péricarde) à liquide riche en protides, en <span class=\"kw-bio\">amylase</span> et en <span class=\"kw-bio\">lipase</span> ; secondaire à une <span class=\"kw-clinique\">fistule</span> canalaire ou à la <span class=\"kw-alerte\">rupture</span> d'un pseudo-kyste dans le péritoine</td></tr>\n          <tr><td><span class=\"kw-alerte\">Thromboses vasculaires</span></td><td>Touchent la <span class=\"kw-clinique\">veine splénique</span> ++, la <span class=\"kw-clinique\">veine porte</span> ou la <span class=\"kw-clinique\">veine mésentérique supérieure</span> → <span class=\"kw-alerte\">HTP segmentaire</span> avec <span class=\"kw-clinique\">varices œsophagiennes et cardio-tubérositaires</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Hémorragies digestives</span></td><td><span class=\"kw-alerte\">Wirsungorragie</span> (<span class=\"kw-clinique\">érosion</span> vasculaire), <span class=\"kw-alerte\">rupture</span> d'un <span class=\"kw-alerte\">pseudo-anévrisme</span> adjacent à un pseudo-kyste, ou <span class=\"kw-alerte\">HTP segmentaire</span> par compression veineuse</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 358 — <span class=\"kw-etio\">Pancréatite aiguë</span> · 247 — <span class=\"kw-etio\">Diabète</span> · 250 — Dénutrition · 279 — <span class=\"kw-etio\">Cirrhose</span></em></p>","frequence":2},{"id":"281-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principales anomalies biologiques","contenu":"<p>La biologie est <strong>normale en dehors des poussées de <span class=\"kw-etio\">pancréatite aiguë</span></strong>, où la <span class=\"kw-bio\">lipase</span> est élevée. Devant une suspicion de PC, le bilan <span class=\"kw-ttt\">biologique</span> a <strong>deux objectifs</strong> : rechercher une étiologie alcoolique et dépister <span class=\"kw-clinique\">les</span> complications.</p>\n      <table >\n        <thead><tr><th>Objectif du bilan</th><th>Anomalies / examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Arguments pour une étiologie alcoolique</td>\n            <td>\n              <span class=\"kw-bio\">Cytolyse</span> prédominant sur l'<strong><span class=\"kw-bio\">ASAT</span></strong> ;<br>\n              Augmentation des <span class=\"kw-bio\">γ-GT</span> ;<br>\n              Augmentation du <span class=\"kw-bio\">VGM</span> ;<br>\n              <span class=\"kw-bio\">Thrombopénie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Dépistage</span> des complications</td>\n            <td>\n              <strong>Si douleur :</strong> <span class=\"kw-bio\">lipase</span> ;<br>\n              <strong><span class=\"kw-clinique\">Cholestase</span></strong> (compression de la VBP) : <span class=\"kw-bio\">γ-GT</span> et <span class=\"kw-bio\">phosphatases alcalines</span> ;<br>\n              <strong><span class=\"kw-etio\">Diabète</span> :</strong> <span class=\"kw-bio\">glycémie à jeun</span> et <span class=\"kw-bio\">HbA1c</span> ;<br>\n              <strong>Hépatopathie alcoolique associée :</strong> <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">électrophorèse des protéines sériques</span> ;<br>\n              <strong>Si <span class=\"kw-clinique\">diarrhée</span> chronique</strong> (insuffisance exocrine) : recherche de <span class=\"kw-clinique\">stéatorrhée</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège ⚠</strong> — le dosage de la <span class=\"kw-bio\">lipase</span> est <strong>inutile en dehors d'une <span class=\"kw-clinique\">poussée</span> douloureuse</strong>.</div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/chronic-pancreatitis-2","label":"Radiopaedia : Chronic pancreatitis 2"},{"href":"https://radiopaedia.org/cases/how-to-read-a-ct-of-the-abdomen-and-pelvis","label":"Radiopaedia : How to read a ct of the abdomen and pelvis"},{"href":"https://radiopaedia.org/articles/pancreatic-ducts","label":"Radiopaedia : Pancreatic ducts"},{"href":"https://radiopaedia.org/articles/magnetic-resonance-cholangiopancreatography-mrcp-2","label":"Radiopaedia : Magnetic resonance cholangiopancreatography mrcp 2"}]},{"id":"281-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens d’imagerie à réaliser au cours d’une pancréatite chronique","contenu":"<p><span class=\"kw-clinique\">Les</span> signes radiologiques de PC sont <strong>souvent absents au début</strong> de la maladie et apparaissent progressivement, quelle que soit la technique. Au <span class=\"kw-def\">stade</span> précoce, l'imagerie ne montre que les signes de <span class=\"kw-etio\">pancréatite aiguë</span> lors des poussées.</p>\n      <p><strong>Signes de chronicité</strong> (apparition progressive) :</p>\n      <ul>\n        <li><span class=\"kw-radio\">Calcifications</span> dans le parenchyme pancréatique (et intra-canalaires) — <strong>signe quasi-pathognomonique de PC</strong></li>\n        <li><span class=\"kw-radio\">Dilatation et irrégularités du canal de Wirsung</span> + dilatations « en flammèches » des canaux secondaires</li>\n        <li><span class=\"kw-radio\">Atrophie parenchymateuse</span></li>\n        <li><span class=\"kw-radio\">Pseudo-kystes</span></li>\n      </ul>\n      <p><strong>Hiérarchie des examens d'imagerie :</strong></p>\n      <table >\n        <thead><tr><th>Examen</th><th>Place et caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM avec et sans injection</span></td>\n            <td><strong>1ʳᵉ intention et examen de référence</strong> ; la phase <strong>sans injection</strong> est le meilleur examen pour repérer <span class=\"kw-clinique\">les</span> <span class=\"kw-radio\">calcifications</span> ; montre les signes de PA / PC, élimine les diagnostics différentiels et révèle les complications</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">CPRM (Wirsungo-IRM)</span></td>\n            <td>Cholangio-pancréatographie par résonance magnétique, <strong>non invasive</strong> (ni <span class=\"kw-clinique\">irradiation</span> ni effet indésirable) ; tend à devenir l'examen de référence ; examen de référence pour la <strong>cartographie canalaire</strong> (irrégularités débutantes, dilatations, sténoses, lithiases, fistules) ; moins performante pour le parenchyme et <span class=\"kw-alerte\">ne visualise PAS les calcifications</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échoendoscopie</span></td>\n            <td><strong>3ᵉ intention</strong>, <strong>invasive</strong> (sous anesthésie générale) ; très grande sensibilité pour <span class=\"kw-clinique\">les</span> anomalies du parenchyme et des canaux en cas de <strong>PC débutante</strong> ; permet aussi le <span class=\"kw-ttt\">drainage</span> des pseudo-kystes et la réalisation de ponctions à visée anatomopathologique (présentation pseudo-<span class=\"kw-etio\">tumorale</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">ASP et échographie</span></td>\n            <td>Examens de <strong>découverte fortuite</strong>, à ne pas demander pour le diagnostic ; l'<strong><span class=\"kw-imagerie\">ASP</span></strong> peut montrer des <span class=\"kw-radio\">calcifications</span> en regard de l'aire pancréatique (<span class=\"kw-chiffre\">T12-L2</span>) ; l'<span class=\"kw-imagerie\">échographie</span> <strong>ne voit pas la totalité du pancréas dans <span class=\"kw-chiffre\">≥ 1</span>/3 des cas</strong> (organe postérieur masqué par <span class=\"kw-clinique\">les</span> gaz digestifs)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Discriminant clé</strong> — la <span class=\"kw-imagerie\">TDM sans injection</span> voit <span class=\"kw-clinique\">les</span> <span class=\"kw-radio\">calcifications</span> ; la <span class=\"kw-imagerie\">CPRM</span> en est <strong>aveugle</strong>.</div>","frequence":2},{"id":"281-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître la chronologie d’évolution clinique d’une pancréatite chronique","contenu":"<p>La PC évolue en plusieurs phases sur <span class=\"kw-chiffre\">15 à 20 ans</span> : <span class=\"kw-clinique\">les</span> manifestations aiguës douloureuses dominent au début, les complications chroniques prennent le relais ensuite.</p>\n      <table >\n        <thead><tr><th>Période</th><th>Tableau clinique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&lt; 5 ans</span></td><td>Manifestations douloureuses et complications aiguës : douleur chronique, poussées de PA, <span class=\"kw-clinique\">amaigrissement</span> lié aux douleurs ; <span class=\"kw-clinique\">les</span> complications aiguës (pseudo-kystes, compression de la VBP) augmentent de fréquence</td></tr>\n          <tr><td><span class=\"kw-chiffre\">5 à 10 ans</span></td><td>Phénomènes douloureux et PA plus rares ; pseudo-kystes et compression de la VBP encore présents</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 10 ans</span></td><td>Douleurs, PA, pseudo-kystes et compression de la VBP disparaissent ; le pancréas est désormais calcifié et fibreux ; <span class=\"kw-clinique\">les</span> complications chroniques augmentent en fréquence (compressions digestives, veineuses et biliaires)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 15 ans</span></td><td>Prédominance du <span class=\"kw-etio\">diabète secondaire</span> et de l'<span class=\"kw-etio\">insuffisance pancréatique exocrine</span> ; au <span class=\"kw-def\">stade</span> tardif, il est fréquent que seuls ces deux éléments persistent</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Pronostic</span></strong> — la <span class=\"kw-alerte\">surmortalité</span> des malades atteints de PC alcoolique est de <span class=\"kw-chiffre\">30 à 35 %</span>. La PC n'est cependant responsable du décès que dans <span class=\"kw-chiffre\">1/4 à 1/3</span> des cas : <span class=\"kw-clinique\">les</span> autres complications de l'alcoolo-<span class=\"kw-etio\">tabagisme</span> sont la principale cause de surmortalité —</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Cancers ORL, pulmonaire, œsophagien</span></li>\n        <li><span class=\"kw-etio\">HTA</span>, <span class=\"kw-alerte\">insuffisance coronarienne</span></li>\n        <li><span class=\"kw-etio\">Hépatopathie alcoolique</span> (la PC survient pratiquement toujours avant la <span class=\"kw-etio\">cirrhose</span> alcoolique)</li>\n      </ul>","frequence":0},{"id":"281-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge de la pancréatite chronique, de l’insuffisance exocrine, endocrine et du sevrage alcoolo tabagique","contenu":"<p>Objectif dense — la prise en charge se structure par axes thérapeutiques. Le <span class=\"kw-ttt\">sevrage</span> alcoolo-tabagique en est le socle.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Principes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Sevrage</span> alcoolo-tabagique</td>\n            <td>\n              <strong><span class=\"kw-ttt\">Sevrage</span> du <span class=\"kw-etio\">tabac</span></strong> — essentiel : <span class=\"kw-chiffre\">divise par 2</span> le risque de <span class=\"kw-clinique\">poussée</span> de PA et limite le risque de décès par cancer ou affection cardiovasculaire ;<br>\n              <strong><span class=\"kw-ttt\">Sevrage</span> de l'<span class=\"kw-etio\">alcool</span></strong> — immédiat, total et définitif : efficace sur la douleur (contrôle ou diminution dans <span class=\"kw-chiffre\">50 %</span> des cas), influence favorablement <span class=\"kw-clinique\">les</span> traitements associés ; prévention du <span class=\"kw-clinique\">syndrome de sevrage</span> par <span class=\"kw-ttt\">hyperhydratation</span>, <span class=\"kw-ttt\">vitaminothérapie B1-B6</span> ± <span class=\"kw-ttt\">benzodiazépine</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Traitement de la douleur</td>\n            <td>\n              Complexe et pluridisciplinaire (recours aux spécialistes de la douleur) :<br>\n              <strong>Non spécifique :</strong> <span class=\"kw-ttt\">sevrage</span> alcoolo-tabagique + <span class=\"kw-ttt\">antalgiques de palier 1 ou 2</span>, recours fréquent aux <span class=\"kw-ttt\">morphiniques</span> ;<br>\n              <strong>Spécifique :</strong> <span class=\"kw-ttt\">anti-inflammatoires</span> et <span class=\"kw-ttt\">prégabaline</span> ; <strong><span class=\"kw-imagerie\">endoscopie</span></strong> (<span class=\"kw-ttt\">sphinctérotomie</span> + prothèse dans le canal de Wirsung) ; <strong><span class=\"kw-ttt\">chirurgie</span></strong> de dérivation du canal pancréatique si <span class=\"kw-clinique\">diamètre</span> &gt; <span class=\"kw-chiffre\">5 mm</span> ;<br>\n              <strong>Résection chirurgicale :</strong> réservée aux cas non contrôlés par le traitement médical ou endoscopique\n            </td>\n          </tr>\n          <tr>\n            <td>Pseudo-kystes</td>\n            <td>À traiter seulement si compliqués, de grande taille (<span class=\"kw-chiffre\">&gt; 6 cm</span>) ou ne régressant pas au cours du <span class=\"kw-def\">suivi</span> : <strong><span class=\"kw-ttt\">drainage endoscopique</span> en 1ʳᵉ intention</strong>, <span class=\"kw-ttt\">chirurgie</span> (dérivation ou résection) en cas d'échec</td>\n          </tr>\n          <tr>\n            <td>Insuffisance exocrine</td>\n            <td>En cas d'<span class=\"kw-clinique\">amaigrissement</span> ou de <span class=\"kw-clinique\">stéatorrhée</span> : <span class=\"kw-ttt\">extraits pancréatiques gastro-protégés</span> (gélules), à prendre <strong>pendant <span class=\"kw-clinique\">les</span> repas</strong>, <strong>à vie</strong></td>\n          </tr>\n          <tr>\n            <td>Insuffisance endocrine</td>\n            <td>Prise en charge classique des troubles de la glycorégulation, recours fréquent à l'<span class=\"kw-ttt\">insuline</span> ; <span class=\"kw-alerte\">risque accru d'hypoglycémie</span> ⭐ — favorisé par : <span class=\"kw-etio\">consommation d'<span class=\"kw-etio\">alcool</span></span> (carence en B1), mauvaise observance des extraits pancréatiques, perte des cellules α productrices de <span class=\"kw-ttt\">glucagon</span>, gastroparésie</td>\n          </tr>\n          <tr>\n            <td>Autres complications</td>\n            <td>\n              <strong>Dénutrition :</strong> prise en charge nutritionnelle dédiée ;<br>\n              <strong>Sténoses biliaires :</strong> dérivation chirurgicale cholédoco-duodénale ou jéjunale, ou prothèse par voie endoscopique ;<br>\n              <strong>Compression duodénale :</strong> traitement d'un pseudo-kyste s'il en est responsable, sinon dérivation digestive chirurgicale ;<br>\n              <strong>Épanchements des séreuses :</strong> jeûne + <span class=\"kw-ttt\">nutrition parentérale</span> + prothèse dans le canal pancréatique par voie endoscopique pour « shunter » la <span class=\"kw-clinique\">fistule</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 75 — Addiction <span class=\"kw-etio\">Tabac</span></em></p>","frequence":1}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-alerte\">Hémorragie digestive</span> : <span class=\"kw-alerte\">wirsungorragie</span> (<span class=\"kw-clinique\">érosion</span> vasculaire) ou <span class=\"kw-alerte\">rupture</span> d’un <span class=\"kw-alerte\">pseudo-anévrisme</span> au <span class=\"kw-def\">contact</span> d’un <span class=\"kw-def\">pseudo-kyste</span></li><li><span class=\"kw-alerte\">Hypertension portale segmentaire</span> par <span class=\"kw-etio\">thrombose de la veine splénique</span> (ou porte / mésentérique sup.) → <span class=\"kw-alerte\">varices œsophagiennes et cardio-tubérositaires</span></li><li><span class=\"kw-alerte\">Angiocholite</span> sur compression de la <span class=\"kw-def\">VBP intrapancréatique</span> (<span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">ictère</span> + <span class=\"kw-clinique\">douleur</span>)</li><li><span class=\"kw-clinique\">Ictère</span> / <span class=\"kw-clinique\">cholestase</span> : compression de la VBP — mais devant un <span class=\"kw-clinique\">ictère</span>, évoquer en 1ᵉʳ une <span class=\"kw-etio\">hépatopathie alcoolique</span> ; l’<span class=\"kw-imagerie\">échographie</span> tranche en montrant (ou non) une dilatation des voies biliaires</li><li><span class=\"kw-clinique\">Vomissements</span> · <span class=\"kw-clinique\">intolérance alimentaire</span> : <span class=\"kw-def\">compression duodénale</span> (fibrose, inflammation ou pseudo-kyste)</li><li><span class=\"kw-alerte\">Hypoglycémies</span> du <span class=\"kw-def\">diabète secondaire</span> (favorisées par l’<span class=\"kw-etio\">alcool</span> via la carence en <span class=\"kw-bio\">B1</span>, la baisse du <span class=\"kw-bio\">glucagon</span> et la mauvaise observance des extraits) — tombé en annale</li><li><span class=\"kw-clinique\">Amaigrissement</span> · <span class=\"kw-clinique\">altération de l’état général</span> : évoquer une <span class=\"kw-etio\">dégénérescence en adénocarcinome pancréatique</span>, surtout sur forme <span class=\"kw-def\">pseudo-tumorale</span></li><li><span class=\"kw-clinique\">Ascite</span> (± épanchement pleural/péricardique) riche en <span class=\"kw-bio\">amylase</span> et <span class=\"kw-bio\">lipase</span> : <span class=\"kw-def\">fistule pancréatique</span> ou <span class=\"kw-alerte\">rupture</span> d’un pseudo-kyste</li></ul>","principes":"<p>Le <span class=\"kw-ttt\">sevrage alcoolo-tabagique</span> est le <strong>socle</strong> de la prise en charge ; <span class=\"kw-clinique\">les</span> autres mesures (antalgie, <span class=\"kw-ttt\">drainage</span>, supplémentation) s’y ajoutent. Prise en charge de la douleur <strong>complexe et pluridisciplinaire</strong>.</p><p><strong><span class=\"kw-ttt\">Sevrage</span> alcoolo-tabagique <span class=\"q\">— socle</span></strong></p><ul><li><span class=\"kw-ttt\">Sevrage tabagique</span> essentiel : divise par <span class=\"kw-chiffre\">2</span> le risque de <span class=\"kw-clinique\">poussée</span> de <span class=\"kw-def\">PA</span> et limite la <span class=\"kw-def\">mortalité</span> (cancer, cardiovasculaire)</li><li><span class=\"kw-ttt\">Sevrage alcoolique</span> immédiat, total et définitif : contrôle ou diminue la <span class=\"kw-clinique\">douleur</span> dans <span class=\"kw-chiffre\">50 %</span> des cas et améliore <span class=\"kw-clinique\">les</span> résultats des traitements endoscopiques/chirurgicaux</li><li>Prévention du <span class=\"kw-alerte\">syndrome de sevrage</span> : <span class=\"kw-ttt\">hyperhydratation</span>, <span class=\"kw-ttt\">vitamines B1-B6</span> ± <span class=\"kw-ttt\">benzodiazépine</span></li></ul><p><strong>Traitement de la douleur <span class=\"q\">— escalade</span></strong></p><ul><li>Non spécifique : <span class=\"kw-ttt\">sevrage</span> + <span class=\"kw-ttt\">antalgiques palier 1 ou 2</span>, voire recours fréquent aux <span class=\"kw-ttt\">morphiniques</span></li><li>Spécifique : <span class=\"kw-ttt\">anti-inflammatoires</span>, <span class=\"kw-ttt\">prégabaline</span></li><li>Hyperpression canalaire : <span class=\"kw-ttt\">dérivation chirurgicale</span> du canal pancréatique si <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-chiffre\">&gt; 5 mm</span>, ou <span class=\"kw-ttt\">sphinctérotomie endoscopique + prothèse pancréatique</span></li><li><span class=\"kw-ttt\">Résection chirurgicale</span> réservée aux cas non contrôlés par le médical/endoscopique</li></ul><p><strong>Pseudo-kystes</strong></p><p><span class=\"kw-ttt\">drainage endoscopique</span> en 1ʳᵉ intention, <span class=\"kw-ttt\">chirurgie</span> (dérivation/résection) en cas d’échec</p><ul><li>À traiter seulement si <span class=\"kw-alerte\">compliqués</span>, de grande taille (<span class=\"kw-chiffre\">&gt; 6 cm</span>) ou ne régressant pas au cours du <span class=\"kw-def\">suivi</span></li></ul><p><strong><span class=\"kw-clinique\">Insuffisance pancréatique exocrine</span></strong></p><p><span class=\"kw-ttt\">extraits pancréatiques gastro-protégés</span>, pris pendant <span class=\"kw-clinique\">les</span> repas, <span class=\"kw-chiffre\">à vie</span></p><ul><li>Indication : <span class=\"kw-clinique\">amaigrissement</span> ou <span class=\"kw-clinique\">stéatorrhée</span></li></ul><p><strong>Insuffisance pancréatique endocrine (<span class=\"kw-etio\">diabète</span>)</strong></p><ul><li><span class=\"kw-etio\">Diabète</span> secondaire : prise en charge classique de la glycorégulation, recours fréquent à l’<span class=\"kw-ttt\">insuline</span></li><li><span class=\"kw-alerte\">Risque accru d’hypoglycémie</span> : <span class=\"kw-etio\">alcool</span> (carence B1), perte des cellules α productrices de <span class=\"kw-bio\">glucagon</span>, mauvaise observance des extraits, <span class=\"kw-etio\">gastroparésie</span></li></ul><p><strong>Complications biliaires, duodénales et séreuses</strong></p><ul><li><span class=\"kw-def\">Sténose biliaire</span> : <span class=\"kw-ttt\">dérivation chirurgicale</span> (cholédoco-duodénale/jéjunale) ou <span class=\"kw-ttt\">prothèse endoscopique</span></li><li><span class=\"kw-def\">Compression duodénale</span> : traiter le pseudo-kyste responsable, sinon <span class=\"kw-ttt\">dérivation digestive chirurgicale</span></li><li><span class=\"kw-def\">Épanchement des séreuses</span> : <span class=\"kw-ttt\">jeûne</span> + <span class=\"kw-ttt\">nutrition parentérale</span> + <span class=\"kw-ttt\">prothèse canalaire endoscopique</span> pour « shunter » la <span class=\"kw-clinique\">fistule</span></li><li>Traitement de la <span class=\"kw-clinique\">dénutrition</span></li></ul>","suivi":"<p>Maladie évoluant sur <span class=\"kw-chiffre\">15 à 20 ans</span>. Surmortalité de la PC alcoolique <span class=\"kw-chiffre\">30-35 %</span>, mais la PC n’est responsable du décès que dans <span class=\"kw-chiffre\">1/4 à 1/3</span> des cas : principale cause de décès = autres complications alcoolo-tabagiques (<span class=\"kw-etio\">cancers ORL/pulmonaire/œsophagien</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">insuffisance coronarienne</span>, <span class=\"kw-etio\">hépatopathie alcoolique</span>).</p><p><strong>Chronologie d’<span class=\"kw-clinique\">évolution</span></strong></p><ul><li><span class=\"kw-chiffre\">&lt; 5 ans</span> : <span class=\"kw-clinique\">douleurs</span> et complications aiguës — poussées de <span class=\"kw-def\">PA</span> (<span class=\"kw-chiffre\">40-50 %</span>), pseudo-kystes, compression de la VBP</li><li><span class=\"kw-chiffre\">5-10 ans</span> : douleurs et poussées de PA plus rares ; pseudo-kystes et compression VBP encore présents</li><li><span class=\"kw-chiffre\">&gt; 10 ans</span> : douleurs, PA, pseudo-kystes et compression VBP disparaissent ; pancréas <span class=\"kw-radio\">calcifié et fibreux</span></li><li><span class=\"kw-chiffre\">&gt; 15 ans</span> : prédominance du <span class=\"kw-def\">diabète secondaire</span> et de l’<span class=\"kw-def\">insuffisance pancréatique exocrine</span></li></ul><p><strong><span class=\"kw-def\">Dépistage</span> des complications chroniques</strong></p><ul><li><span class=\"kw-etio\">Diabète</span> : <span class=\"kw-bio\">glycémie à jeun</span>, <span class=\"kw-bio\">HbA1c</span></li><li>Insuffisance exocrine : <span class=\"kw-clinique\">stéatorrhée</span>, <span class=\"kw-bio\">élastase fécale</span> (taux effondré)</li><li>Dénutrition / carences : vitamines liposolubles <span class=\"kw-bio\">A, D, E, K</span>, <span class=\"kw-bio\">B12</span>, <span class=\"kw-bio\">B9</span>, oligo-éléments (calcium, zinc) → risque d’<span class=\"kw-def\">ostéoporose</span></li></ul><p><strong>Dégénérescence</strong></p><p>ne justifie <strong>pas</strong> de <span class=\"kw-def\">surveillance</span> particulière</p><ul><li>La PC augmente le risque d’<span class=\"kw-etio\">adénocarcinome pancréatique</span>, mais le risque reste faible (<span class=\"kw-chiffre\">&lt; 5 %</span>)</li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/chronic-pancreatitis-2","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/cases/how-to-read-a-ct-of-the-abdomen-and-pelvis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/pancreatic-ducts","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/magnetic-resonance-cholangiopancreatography-mrcp-2","label":"radiopaedia.org"}],"cards":[{"i":"7dbf1995b2d5","n":281,"o":"281-1","u":"Définition","t":"Connaître la définition d’une pancréatite chronique","q":"Quels sont les tissus du pancréas touchés par la pancréatite chronique et dans quel ordre ?","a":"<p>L'atteinte par la pancréatite chronique se fait en deux temps :</p><ul><li>En premier, le <strong>tissu exocrine</strong> (acini et canaux pancréatiques) est touché.</li><li>Ensuite, le <strong>tissu endocrine</strong> (îlots de Langerhans) est atteint.</li></ul>"},{"i":"9c4b34620e14","n":281,"o":"281-1","u":"Définition","t":"Connaître la définition d’une pancréatite chronique","q":"Quel est le mécanisme conduisant à la pancréatite chronique ?","a":"<p>La pancréatite chronique résulte de <strong>l'inhibition ou du dépassement des mécanismes de protection contre l'auto-digestion</strong> du pancréas. La répétition des pancréatites aiguës active les mécanismes de réparation, entraînant un dépôt de fibrose qui désorganise l'architecture de la glande et altère son fonctionnement. Les canaux pancréatiques deviennent sténosés de façon irrégulière et des calcifications peuvent se former en leur sein.</p>"},{"i":"ea110e172600","n":281,"o":"281-1","u":"Définition","t":"Connaître la définition d’une pancréatite chronique","q":"Quelle est la définition d'une pancréatite chronique ?","a":"<p>La pancréatite chronique (PC) est une <strong>inflammation chronique du pancréas</strong> qui entraîne une <strong>fibrose mutilante progressive</strong> du parenchyme pancréatique et, dans un second temps, une destruction fonctionnelle ± complète de la glande.</p>"},{"i":"2ba6eb4ad537","n":281,"o":"281-3","u":"Etiologies","t":"Connaître la principale cause et facteur de risque de la pancréatite chronique","q":"Quelle dose d'alcool est habituellement associée à la pancréatite chronique et y a-t-il une dose seuil stricte ?","a":"<p>Une consommation estimée à <strong>100 à 150 g d'alcool pur par jour</strong> pendant <strong>10 à 15 ans</strong> est habituellement associée. Cependant, il n'existe <strong>pas de réelle dose-seuil</strong>, et seulement moins de 5 % des consommateurs excessifs développent une pancréatite chronique, soulignant une susceptibilité individuelle.</p>"},{"i":"cbfb53204e22","n":281,"o":"281-3","u":"Etiologies","t":"Connaître la principale cause et facteur de risque de la pancréatite chronique","q":"Quelle est la principale cause de pancréatite chronique en Occident et dans quelle proportion est-elle impliquée ?","a":"<p>La principale cause de pancréatite chronique en Occident est la consommation excessive d'<strong>alcool</strong>, responsable de <strong>70 à 85 %</strong> des cas.</p>"},{"i":"f201cec9cf7a","n":281,"o":"281-3","u":"Etiologies","t":"Connaître la principale cause et facteur de risque de la pancréatite chronique","q":"Quel est le principal facteur de risque indépendant de la pancréatite chronique et quelle est son influence ?","a":"<p>Le <strong>tabac</strong> est un facteur de risque indépendant de la pancréatite chronique. Il est associé dans plus de 80 % des pancréatites chroniques d'origine alcoolique et constitue un <strong>facteur péjoratif</strong> qui aggrave l'évolution de la maladie.</p>"},{"i":"2ab3ce0e2671","n":281,"o":"281-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur de pancréatite chronique","q":"Quel est un signe clinique fréquemment associé à la douleur de la pancréatite chronique, et pourquoi survient-il ?","a":"<p>L'<strong>amaigrissement</strong> est un signe fréquemment associé à la douleur de la pancréatite chronique. Il survient car les patients restreignent leur alimentation pour éviter de déclencher ou d'aggraver les douleurs post-prandiales.</p>"},{"i":"a151a2555580","n":281,"o":"281-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur de pancréatite chronique","q":"Quelle est la fréquence de la douleur pancréatique chez les patients atteints de pancréatite chronique ?","a":"<p>La douleur pancréatique est présente chez <strong>80 %</strong> des patients atteints de pancréatite chronique.</p>"},{"i":"b05ab4f13402","n":281,"o":"281-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur de pancréatite chronique","q":"Sous quelles formes cliniques la douleur de la pancréatite chronique peut-elle se présenter ?","a":"<p>La douleur de la pancréatite chronique peut se présenter sous deux formes :</p><ul><li><strong>Type A</strong> : poussées douloureuses intermittentes, séparées par des périodes de rémission.</li><li>Douleur continue avec des <strong>accès douloureux plus vifs</strong>.</li></ul>"},{"i":"c8d2ac08fd5f","n":281,"o":"281-5","u":"Diagnostic positif","t":"Connaître les caractéristiques de la douleur de pancréatite chronique","q":"L'examen physique est-il utile pour le diagnostic de la douleur dans la pancréatite chronique ?","a":"<p>Non, l'examen physique est généralement <strong>pauvre</strong> et n'objective <strong>aucun signe physique spécifique</strong>, car le pancréas est un organe profond et normalement impalpable.</p>"}]};